-- --------------------------------------------------------

--
-- Table structure for table `security_benefits`
--

CREATE TABLE `security_benefits` (
  `id` bigint UNSIGNED NOT NULL,
  `category_id` bigint UNSIGNED NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `label` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `potential_value` text COLLATE utf8mb4_unicode_ci,
  `context` json DEFAULT NULL,
  `sort_order` smallint UNSIGNED NOT NULL DEFAULT '0',
  `is_manual` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `security_benefits`
--

INSERT INTO `security_benefits` (`id`, `category_id`, `slug`, `label`, `title`, `description`, `potential_value`, `context`, `sort_order`, `is_manual`, `created_at`, `updated_at`) VALUES
(1, 1, 'xdr-endpoint-visibility', 'Endpoint visibility', 'Understand device activity', 'Use endpoint telemetry to review device identity, software posture, process and file events, and the activity surrounding an alert.', 'More context about potentially affected endpoints', NULL, 1, 1, '2026-11-27 02:02:43', '2026-11-27 02:02:43'),
(2, 1, 'xdr-workload-visibility', 'Workload visibility', 'Include servers, containers, and services', 'Where supported workload sources are connected, include server, container, and service activity when investigating alerts and affected assets.', 'Broader context across managed workloads', NULL, 2, 1, '2026-11-27 02:02:43', '2026-11-27 02:02:43'),
(3, 1, 'xdr-network-detection', 'Network detection', 'Follow suspicious communication paths', 'Use available network-flow, DNS, connection, and gateway telemetry to investigate unusual destinations, beaconing, or movement between systems.', 'Broader understanding of communication patterns', NULL, 3, 1, '2026-11-27 02:02:43', '2026-11-27 02:02:43'),
(4, 1, 'xdr-identity-context', 'Identity context', 'Connect actions with users and identities', 'Correlate sign-in, privilege, directory, and application events to help assess account compromise, misuse, and suspicious access.', 'More informed investigation of account activity', NULL, 4, 1, '2026-11-27 02:02:43', '2026-11-27 02:02:43'),
(5, 1, 'xdr-cloud-visibility', 'Cloud visibility', 'Include cloud and SaaS activity', 'Where supported data sources are connected, include cloud control-plane, workload, and SaaS events in cross-domain investigations.', 'More context across connected cloud services', NULL, 5, 1, '2026-11-27 02:02:43', '2026-11-27 02:02:43'),
(6, 1, 'xdr-email-security', 'Email security', 'Relate messaging threats to other activity', 'Where email-security telemetry is available, connect suspicious messages, URLs, attachments, and user reports with related identity and endpoint events.', 'A clearer view of cross-channel incidents', NULL, 6, 1, '2026-11-27 02:02:43', '2026-11-27 02:02:43'),
(7, 1, 'xdr-correlated-detections', 'Correlated detections', 'Join related alerts into stronger signals', 'Relate endpoint, network, identity, cloud, and email events by time, asset, account, and indicator instead of reviewing each alert in isolation.', 'More meaningful incident context for analysts', NULL, 7, 1, '2026-11-27 02:02:43', '2026-11-27 02:02:43'),
(8, 1, 'xdr-soc-triage', 'SOC triage', 'Prioritize alerts with shared context', 'Give analysts related events, asset criticality, vulnerability context, and known indicators to support consistent severity and escalation decisions.', 'More focused analyst attention', NULL, 8, 1, '2026-11-27 02:02:43', '2026-11-27 02:02:43'),
(9, 1, 'xdr-incident-response', 'Incident response', 'Coordinate containment and recovery', 'Support a common incident workflow for scoping impact, assigning owners, recording approvals, and coordinating containment and recovery.', 'Clearer handoffs and repeatable response', NULL, 9, 1, '2026-11-27 02:02:43', '2026-11-27 02:02:43'),
(10, 1, 'xdr-root-cause-analysis', 'Root-cause analysis', 'Reconstruct how an incident unfolded', 'Build a timeline from related alerts and telemetry to trace initial access, execution, persistence, privilege changes, and subsequent activity.', 'Better-supported remediation decisions', NULL, 10, 1, '2026-11-27 02:02:43', '2026-11-27 02:02:43'),
(11, 1, 'xdr-attack-surface-visibility', 'Attack-surface visibility', 'Highlight exposed or unmanaged assets', 'Compare discovered assets and activity with expected inventory to identify potentially exposed, misconfigured, or unmonitored systems.', 'More targeted exposure reduction', NULL, 11, 1, '2026-11-27 02:02:43', '2026-11-27 02:02:43'),
(12, 1, 'xdr-insider-threat-context', 'Insider-threat context', 'Review unusual activity in context', 'Correlate access and endpoint events to help authorized teams investigate anomalous activity while respecting policy and privacy controls.', 'More context for careful, policy-led review', NULL, 12, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(13, 1, 'xdr-ransomware-readiness', 'Ransomware readiness', 'Connect precursors to response plans', 'Relate suspicious encryption, privilege escalation, backup access, and lateral movement indicators to support early investigation and rehearsed response.', 'More prepared incident coordination', NULL, 13, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(14, 1, 'xdr-malware-investigation', 'Malware investigation', 'Trace suspicious files and execution', 'Combine process, file, endpoint, and network events with validated indicators to investigate suspected malware activity.', 'A clearer view of suspected infection scope', NULL, 14, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(15, 1, 'xdr-lateral-movement', 'Lateral movement', 'Follow activity between systems', 'Relate authentication, remote access, and network events across assets to investigate possible movement after an initial compromise.', 'Better-supported incident scoping', NULL, 15, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(16, 1, 'xdr-vulnerability-context', 'Vulnerability context', 'Prioritize alerts using exposure data', 'Add known asset and vulnerability context to detections to help assess which findings may carry greater operational risk.', 'More risk-aware triage', NULL, 16, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(17, 1, 'xdr-threat-intelligence', 'Threat intelligence', 'Add context to suspicious indicators', 'Compare observed domains, addresses, files, and behaviors with maintained threat intelligence, while validating source quality and freshness.', 'Better-informed investigation priorities', NULL, 17, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(18, 1, 'xdr-asset-inventory', 'Asset inventory', 'Relate detections to asset ownership', 'Use maintained asset identity, role, owner, and criticality data to make alerts more actionable and identify inventory gaps.', 'Better incident scoping and accountability', NULL, 18, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(19, 1, 'xdr-cases-and-evidence', 'Cases and evidence', 'Keep investigation notes and evidence together', 'Maintain incident timelines, linked alerts, analyst notes, and evidence references in a consistent case record with controlled access.', 'More complete investigations and handoffs', NULL, 19, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(20, 1, 'xdr-automation-and-remediation', 'Automation and remediation', 'Standardize repeatable response steps', 'Automate approved enrichment, notifications, and low-risk remediation tasks, while requiring human review for disruptive actions.', 'Less repetitive work with safer controls', NULL, 20, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(21, 1, 'xdr-continuous-improvement', 'Continuous improvement', 'Learn from incidents and tune coverage', 'Review incident outcomes, response timing, detection gaps, and recurring causes to refine playbooks, data coverage, and detection logic.', 'More adaptive security operations', NULL, 21, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(22, 2, 'siem-collection', 'Collection', 'Bring security-relevant logs together', 'Collect agreed event sources from applications, operating systems, identity platforms, networks, and cloud services through managed integrations.', 'A central foundation for monitoring', NULL, 1, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(23, 2, 'siem-parsing-and-normalization', 'Parsing and normalization', 'Make events consistent and searchable', 'Parse source-specific formats into common fields, validate timestamps, and normalize identities and event types for analysis.', 'More useful cross-source queries', NULL, 2, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(24, 2, 'siem-retention', 'Retention', 'Keep event history for defined periods', 'Set retention tiers and disposal schedules that balance investigation and audit needs with privacy, policy, and storage constraints.', 'More predictable event availability and lifecycle', NULL, 3, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(25, 2, 'siem-governance', 'Governance', 'Set clear data ownership and controls', 'Define source owners, access permissions, data quality reviews, and approval practices for collected event information.', 'More accountable and controlled log management', NULL, 4, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(26, 2, 'siem-correlation', 'Correlation', 'Connect activity across systems', 'Use rules and time-based relationships to identify sequences spanning users, hosts, applications, and network services.', 'Patterns that isolated logs can obscure', NULL, 5, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(27, 2, 'siem-rule-management', 'Rule management', 'Maintain detections as controlled content', 'Version, review, test, document, and retire detection rules with clear ownership and change approval.', 'More understandable and maintainable alert logic', NULL, 6, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(28, 2, 'siem-behavioral-analytics-and-ueba', 'Behavioral analytics and UEBA', 'Spot deviations from expected activity', 'Analyze event patterns for unusual behavior by user, service, or asset; validate baselines and account for legitimate changes before escalation.', 'Additional signals for analyst investigation', NULL, 7, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(29, 2, 'siem-compliance-reporting', 'Compliance reporting', 'Support evidence and audit preparation', 'Create scoped reports from retained event records and documented controls to support internal audits and applicable compliance reviews.', 'More organized reporting workflows', NULL, 8, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(30, 2, 'siem-audit-trails', 'Audit trails', 'Track access and administrative changes', 'Retain relevant account, configuration, and privileged-action records so authorized reviewers can reconstruct administrative activity.', 'Improved accountability and traceability', NULL, 9, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(31, 2, 'siem-search-and-forensics', 'Search and forensics', 'Investigate historical event sequences', 'Search across normalized event history to establish timelines, scope affected identities and assets, and support post-incident analysis.', 'Faster evidence discovery', NULL, 10, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(32, 2, 'siem-dashboards-and-alerts', 'Dashboards and alerts', 'Make monitoring status visible', 'Use role-specific dashboards and alert routes to surface priority detections, ingestion health, and monitoring trends.', 'Clearer operational awareness', NULL, 11, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(33, 2, 'siem-integrations', 'Integrations', 'Connect existing security and IT tools', 'Integrate supported identity, endpoint, cloud, ticketing, and threat-intelligence sources with documented ownership and data quality checks.', 'Less fragmented security context', NULL, 12, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(34, 2, 'siem-threat-intelligence', 'Threat intelligence', 'Enrich events with current threat context', 'Compare selected event indicators with maintained intelligence sources and preserve source, confidence, and freshness context for analysts.', 'More informed event triage', NULL, 13, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(35, 2, 'siem-soar-workflows', 'SOAR workflows', 'Orchestrate consistent alert handling', 'Route alerts for enrichment, notification, and case creation using approved playbooks, with human authorization for high-impact actions.', 'More repeatable operations', NULL, 14, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(36, 2, 'siem-false-positive-tuning', 'False-positive tuning', 'Improve signal quality over time', 'Review alert outcomes, tune thresholds and exceptions, and document why a detection changed without hiding meaningful risk.', 'More analyst focus on actionable alerts', NULL, 15, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(37, 2, 'siem-scalability', 'Scalability', 'Plan capacity as event volumes grow', 'Estimate ingestion and search demand, measure storage use, and plan processing capacity as sources and retention needs expand.', 'More predictable growth planning', NULL, 17, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(38, 2, 'siem-high-availability', 'High availability', 'Design for service continuity', 'Where required, plan redundancy, backups, recovery objectives, and health monitoring for the SIEM components and data sources.', 'Better continuity when appropriately engineered', NULL, 18, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(39, 2, 'siem-cost-control', 'Cost control', 'Match collection and retention to risk', 'Measure ingestion volume, prioritize high-value sources, reduce noisy duplication, and review storage and licensing against retention needs.', 'Better-informed security data spend', NULL, 19, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(40, 2, 'siem-real-time-monitoring', 'Real-time monitoring', 'Surface events while response is useful', 'Monitor incoming events and alert on defined conditions with timing expectations matched to source delays and operational coverage.', 'More timely detection opportunities', NULL, 20, 1, '2026-11-27 02:02:44', '2026-11-27 02:02:44'),
(41, 2, 'siem-operational-measurement', 'Operational measurement', 'Review coverage and service health', 'Track ingestion gaps, stale sources, alert workload, investigation outcomes, and response handoffs to guide practical improvements.', 'Clearer monitoring performance', NULL, 21, 1, '2026-11-27 02:02:45', '2026-11-27 02:02:45'),
(42, 3, 'comparison-primary-focus', NULL, 'Primary focus', 'Correlate and respond across connected security layers.', NULL, '{\"xdr\": \"Correlate and respond across connected security layers.\", \"siem\": \"Collect, normalize, search, and analyze event data broadly.\"}', 1, 1, '2026-11-27 02:02:45', '2026-11-27 02:02:45'),
(43, 3, 'comparison-typical-starting-point', NULL, 'Typical starting point', 'Cross-domain detections and incident workflows.', NULL, '{\"xdr\": \"Cross-domain detections and incident workflows.\", \"siem\": \"Central log coverage, retention, queries, and alert rules.\"}', 2, 1, '2026-11-27 02:02:45', '2026-11-27 02:02:45'),
(44, 3, 'comparison-shared-foundation', NULL, 'Shared foundation', 'Reliable telemetry, identity and asset context, and governed response.', NULL, '{\"xdr\": \"Reliable telemetry, identity and asset context, and governed response.\", \"siem\": \"Reliable telemetry, identity and asset context, and governed response.\"}', 3, 1, '2026-11-27 02:02:45', '2026-11-27 02:02:45'),
(45, 4, 'business-reduce-uncertainty-during-incidents', NULL, 'Reduce uncertainty during incidents', 'Shared context, clear ownership, and retained evidence can help teams make and explain response decisions.', NULL, NULL, 1, 1, '2026-11-27 02:02:45', '2026-11-27 02:02:45'),
(46, 4, 'business-use-staff-time-more-deliberately', NULL, 'Use staff time more deliberately', 'Prioritized alerts and repeatable workflows can reduce manual correlation and administrative effort.', NULL, NULL, 2, 1, '2026-11-27 02:02:45', '2026-11-27 02:02:45'),
(47, 4, 'business-strengthen-oversight', NULL, 'Strengthen oversight', 'Documented controls, access, retention, and audit evidence can support governance and review.', NULL, NULL, 3, 1, '2026-11-27 02:02:45', '2026-11-27 02:02:45'),
(48, 4, 'business-improve-investment-decisions', NULL, 'Improve investment decisions', 'Coverage, capacity, alert quality, and outcome measures can inform where to improve or simplify security operations.', NULL, NULL, 4, 1, '2026-11-27 02:02:45', '2026-11-27 02:02:45');

